local Junkie = loadstring(game:HttpGet("https://jnkie.com/sdk/library.lua"))()
Junkie.service = "0xv"
Junkie.identifier = "3758"
Junkie.provider = "Cuty"

local result = (function()
    getgenv().UI_CLOSED = false
    local Players = game:GetService("Players")
    local TweenService = game:GetService("TweenService")
    local UserInputService = game:GetService("UserInputService")

    local Colors = {
        bg       = Color3.fromRGB(15, 15, 15),
        surface  = Color3.fromRGB(10, 10, 10),
        border   = Color3.fromRGB(30, 30, 30),
        borderLt = Color3.fromRGB(48, 54, 61),
        accent   = Color3.fromRGB(84, 101, 255),
        accentDk = Color3.fromRGB(56, 67, 163),
        success  = Color3.fromRGB(60, 210, 120),
        error    = Color3.fromRGB(220, 60, 60),
        warning  = Color3.fromRGB(255, 180, 40),
        text     = Color3.fromRGB(255, 255, 255),
        textSub  = Color3.fromRGB(150, 150, 150),
        textMut  = Color3.fromRGB(100, 100, 100),
    }

    local function tween(o, t, props)
        TweenService:Create(o, TweenInfo.new(t or 0.2, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), props):Play()
    end

    local function hasFileSystemSupport()
        local a = pcall(function() return type(writefile) == "function" end)
        local b = pcall(function() return type(readfile) == "function" end)
        local c = pcall(function() return type(isfile) == "function" end)
        return a and b and c
    end

    local fileSystemSupported = hasFileSystemSupport()

    local function saveVerifiedKey(key)
        if not fileSystemSupported then return false end
        return pcall(function() writefile("verified_key.txt", key) end)
    end

    local function loadVerifiedKey()
        if not fileSystemSupported then return nil end
        local ok, content = pcall(function() return readfile("verified_key.txt") end)
        if not ok or not content then return nil end
        return content
    end

    local function clearSavedKey()
        if not fileSystemSupported then return false end
        return pcall(function() delfile("verified_key.txt") end)
    end

    local UI = {}
    UI.__index = UI

    function UI.new(options)
        local self = setmetatable({}, UI)
        self.options = options or {}
        self.title = self.options.title or "0xv.wtf"
        self.subtitle = self.options.subtitle or "Key Verification"
        self.player = Players.LocalPlayer
        self.gui = nil
        self.hwid = game:GetService("RbxAnalyticsService"):GetClientId()
        self._connections = {}
        return self
    end

    function UI:createUI()
        if self.gui then self.gui:Destroy() end

        self.gui = Instance.new("ScreenGui")
        self.gui.Name = "unknown"
        self.gui.ResetOnSpawn = false
        self.gui.ZIndexBehavior = Enum.ZIndexBehavior.Global
        self.gui.IgnoreGuiInset = true
        if syn then pcall(syn.protect_gui, self.gui) end
        self.gui.Parent = game:GetService("CoreGui")

        local backdrop = Instance.new("Frame")
        backdrop.Size = UDim2.new(1, 0, 1, 0)
        backdrop.BackgroundColor3 = Color3.fromRGB(0, 0, 0)
        backdrop.BackgroundTransparency = 0.5
        backdrop.BorderSizePixel = 0
        backdrop.Parent = self.gui

        local isMobile = UserInputService.TouchEnabled and not UserInputService.KeyboardEnabled

        local main = Instance.new("ImageButton")
        main.Name = "Main"
        main.AnchorPoint = Vector2.new(0.5, 0.5)
        main.Position = UDim2.new(0.5, 0, 0.5, 0)
        main.Size = isMobile and UDim2.new(0, 360, 0, 240) or UDim2.new(0, 460, 0, 250)
        main.BackgroundColor3 = Colors.bg
        main.BorderColor3 = Colors.accent
        main.BorderSizePixel = 1
        main.AutoButtonColor = false
        main.Image = ""
        main.Parent = backdrop

        local title = Instance.new("TextLabel")
        title.Name = "Title"
        title.AnchorPoint = Vector2.new(0.5, 0)
        title.Position = UDim2.new(0.5, 0, 0, 0)
        title.Size = UDim2.new(1, -22, 0, 30)
        title.BackgroundTransparency = 1
        title.Font = Enum.Font.Ubuntu
        title.Text = self.title
        title.TextColor3 = Colors.text
        title.TextSize = 16
        title.TextXAlignment = Enum.TextXAlignment.Left
        title.Parent = main

        local closeButton = Instance.new("TextButton")
        closeButton.Name = "CloseButton"
        closeButton.AnchorPoint = Vector2.new(1, 0)
        closeButton.Position = UDim2.new(1, -10, 0, 8)
        closeButton.Size = UDim2.new(0, 16, 0, 16)
        closeButton.BackgroundColor3 = Colors.surface
        closeButton.BorderColor3 = Colors.border
        closeButton.BorderSizePixel = 1
        closeButton.AutoButtonColor = false
        closeButton.Font = Enum.Font.Ubuntu
        closeButton.Text = "x"
        closeButton.TextColor3 = Colors.textSub
        closeButton.TextSize = 14
        closeButton.Parent = main

        local border = Instance.new("Frame")
        border.AnchorPoint = Vector2.new(0.5, 0)
        border.Position = UDim2.new(0.5, 0, 0, 42)
        border.Size = UDim2.new(1, -20, 0, 1)
        border.BackgroundColor3 = Colors.border
        border.BorderSizePixel = 0
        border.Parent = main

        local content = Instance.new("Frame")
        content.Name = "Content"
        content.AnchorPoint = Vector2.new(0.5, 0)
        content.Position = UDim2.new(0.5, 0, 0, 60)
        content.Size = UDim2.new(1, -40, 1, -80)
        content.BackgroundTransparency = 1
        content.Parent = main

        local subtitle = Instance.new("TextLabel")
        subtitle.Name = "Subtitle"
        subtitle.Position = UDim2.new(0, 0, 0, 0)
        subtitle.Size = UDim2.new(1, 0, 0, 18)
        subtitle.BackgroundTransparency = 1
        subtitle.Font = Enum.Font.Ubuntu
        subtitle.Text = self.subtitle
        subtitle.TextColor3 = Colors.textSub
        subtitle.TextSize = 14
        subtitle.TextXAlignment = Enum.TextXAlignment.Left
        subtitle.Parent = content

        local inputBorder = Instance.new("Frame")
        inputBorder.Name = "InputBorder"
        inputBorder.Position = UDim2.new(0, 0, 0, 34)
        inputBorder.Size = UDim2.new(1, 0, 0, 34)
        inputBorder.BackgroundColor3 = Colors.surface
        inputBorder.BorderColor3 = Colors.border
        inputBorder.BorderSizePixel = 1
        inputBorder.Parent = content

        local keyInput = Instance.new("TextBox")
        keyInput.Name = "KeyInput"
        keyInput.Position = UDim2.new(0, 10, 0, 0)
        keyInput.Size = UDim2.new(1, -20, 1, 0)
        keyInput.BackgroundTransparency = 1
        keyInput.Font = Enum.Font.Ubuntu
        keyInput.PlaceholderText = "Enter your verification key"
        keyInput.PlaceholderColor3 = Colors.textMut
        keyInput.Text = ""
        keyInput.TextColor3 = Colors.text
        keyInput.TextSize = 14
        keyInput.TextXAlignment = Enum.TextXAlignment.Left
        keyInput.TextTruncate = Enum.TextTruncate.AtEnd
        keyInput.ClearTextOnFocus = false
        keyInput.Parent = inputBorder

        local function makeButton(name, text, xScale, xOff, wScale, color)
            local b = Instance.new("TextButton")
            b.Name = name
            b.Position = UDim2.new(xScale, xOff, 0, 84)
            b.Size = UDim2.new(wScale, xOff == 0 and -4 or -4, 0, 34)
            b.BackgroundColor3 = Colors.surface
            b.BorderColor3 = Colors.border
            b.BorderSizePixel = 1
            b.AutoButtonColor = false
            b.Font = Enum.Font.Ubuntu
            b.Text = text
            b.TextColor3 = Colors.textSub
            b.TextSize = 14
            b.Parent = content

            b.MouseEnter:Connect(function()
                tween(b, 0.2, {TextColor3 = color})
                tween(b, 0.2, {BorderColor3 = color})
            end)
            b.MouseLeave:Connect(function()
                tween(b, 0.2, {TextColor3 = Colors.textSub})
                tween(b, 0.2, {BorderColor3 = Colors.border})
            end)
            return b
        end

        local getLinkButton = makeButton("GetLink", "Get Link", 0, 0, 0.5, Colors.accent)
        local verifyButton  = makeButton("Verify", "Verify Key", 0.5, 4, 0.5, Colors.success)

        local statusText = Instance.new("TextLabel")
        statusText.Name = "Status"
        statusText.AnchorPoint = Vector2.new(0.5, 1)
        statusText.Position = UDim2.new(0.5, 0, 1, -8)
        statusText.Size = UDim2.new(1, -40, 0, 16)
        statusText.BackgroundTransparency = 1
        statusText.Font = Enum.Font.Ubuntu
        statusText.Text = ""
        statusText.TextColor3 = Colors.textSub
        statusText.TextSize = 13
        statusText.Parent = main

        self.elements = {
            backdrop = backdrop,
            main = main,
            content = content,
            title = title,
            subtitle = subtitle,
            inputFrame = inputBorder,
            keyInput = keyInput,
            getLinkButton = getLinkButton,
            verifyButton = verifyButton,
            closeButton = closeButton,
            statusText = statusText,
        }

        keyInput.Focused:Connect(function()
            tween(inputBorder, 0.2, {BorderColor3 = Colors.accent})
        end)
        keyInput.FocusLost:Connect(function()
            tween(inputBorder, 0.2, {BorderColor3 = Colors.border})
        end)

        closeButton.MouseEnter:Connect(function() tween(closeButton, 0.2, {TextColor3 = Colors.error, BorderColor3 = Colors.error}) end)
        closeButton.MouseLeave:Connect(function() tween(closeButton, 0.2, {TextColor3 = Colors.textSub, BorderColor3 = Colors.border}) end)

        table.insert(self._connections, closeButton.MouseButton1Click:Connect(function() self:close() end))
        table.insert(self._connections, getLinkButton.MouseButton1Click:Connect(function() self:handleGetLink() end))
        table.insert(self._connections, verifyButton.MouseButton1Click:Connect(function() self:handleVerifyKey() end))
        table.insert(self._connections, keyInput.FocusLost:Connect(function(enter)
            if enter then self:handleVerifyKey() end
        end))

        return self.gui
    end

    function UI:updateStatus(message, color, duration)
        local s = self.elements.statusText
        if not s then return end
        s.Text = message
        s.TextColor3 = color or Colors.textSub
        if duration and duration > 0 then
            task.delay(duration, function()
                if s and s.Text == message then s.Text = "" end
            end)
        end
    end

    function UI:setButtonLoading(button, text, loading)
        button.Text = text
        button.Interactable = not loading
    end

    function UI:shakeInput()
        local frame = self.elements.inputFrame
        if not frame then return end
        local orig = frame.Position
        for _ = 1, 3 do
            tween(frame, 0.05, {Position = orig + UDim2.new(0, -6, 0, 0)})
            task.wait(0.05)
            tween(frame, 0.05, {Position = orig + UDim2.new(0, 6, 0, 0)})
            task.wait(0.05)
        end
        frame.Position = orig
    end

    function UI:showSuccess(message)
        self:updateStatus(message or "Verified", Colors.success, 0)
        tween(self.elements.main, 0.2, {BorderColor3 = Colors.success})
        task.wait(0.8)
    end

    function UI:setLoadingState(isLoading, message)
        local e = self.elements
        if not e then return end
        local vis = not isLoading
        e.subtitle.Visible = vis
        e.inputFrame.Visible = vis
        e.getLinkButton.Visible = vis
        e.verifyButton.Visible = vis
        if isLoading then
            self:updateStatus(message or "Checking...", Colors.accent, 0)
        else
            self:updateStatus("", nil, 0)
        end
    end

    function UI:close()
        getgenv().UI_CLOSED = true
        for _, conn in ipairs(self._connections or {}) do
            pcall(function() conn:Disconnect() end)
        end
        self._connections = {}
        if self.gui then
            tween(self.elements.main, 0.2, {BackgroundTransparency = 1})
            tween(self.elements.backdrop, 0.2, {BackgroundTransparency = 1})
            task.wait(0.2)
            self.gui:Destroy()
            self.gui = nil
        end
        return getgenv().SCRIPT_KEY
    end

    function UI:handleGetLink()
        local link = Junkie.get_key_link()
        if not link then
            self:updateStatus("System not initialized", Colors.error, 3)
            return
        end
        if setclipboard then
            setclipboard(link)
            self:updateStatus("Link copied to clipboard!", Colors.success, 3)
        else
            self:updateStatus("Get link: " .. link, Colors.accent, 10)
        end
    end

    function UI:handleVerifyKey()
        local key = self.elements.keyInput.Text:gsub("%s+", "")
        if key == "" then
            self:updateStatus("Please enter a key", Colors.error, 3)
            self:shakeInput()
            return
        end

        self:setButtonLoading(self.elements.verifyButton, "Verifying", true)
        self:updateStatus("Verifying...", Colors.accent, 0)
        if self.elements.keyInput.Interactable ~= nil then
            self.elements.keyInput.Interactable = false
        end

        local result = Junkie.check_key(key)

        if result and result.valid then
            saveVerifiedKey(key)
            self:updateStatus("Key verified!", Colors.success, 0)
            task.wait(1.5)
            getgenv().SCRIPT_KEY = key
            self:close()
        else
            self:updateStatus("Invalid key", Colors.error, 3)
            self:shakeInput()
            self:setButtonLoading(self.elements.verifyButton, "Verify Key", false)
            if self.elements.keyInput.Interactable ~= nil then
                self.elements.keyInput.Interactable = true
            end
        end
    end

    local ui = UI.new(options)
    ui:createUI()
    ui:setLoadingState(true, "Checking verification...")

    local savedKey = loadVerifiedKey()
    local keyToCheck = savedKey or getgenv().SCRIPT_KEY

    local result = Junkie.check_key(keyToCheck)
    if result and result.valid then
        if result.message == "KEYLESS" then
            ui:showSuccess("Keyless Mode")
            getgenv().SCRIPT_KEY = "KEYLESS"
            ui:close()
            return
        end

        if result.message == "KEY_VALID" then
            if not savedKey and keyToCheck then
                saveVerifiedKey(keyToCheck)
            end
            ui:showSuccess(savedKey and "Saved Key Verified" or "Key Verified")
            getgenv().SCRIPT_KEY = keyToCheck
            ui:close()
            return
        end

        if savedKey and not result.key_valid then
            clearSavedKey()
        end
    end

    ui:setLoadingState(false)

    while not getgenv().UI_CLOSED do
        task.wait(0.1)
    end
    return getgenv().SCRIPT_KEY
end)()

